package ama.transcript;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class Task11PublicationManifestTest {
 static TranscriptAcquisitionBudget.Ledger ledger(){var read=new ama.contract.ConfigArchiveContracts.ArchiveReadBudget(65536,1000000,100,100,16,10000,16,128,65536,65536,1000000,65536,100,1000,10000);var canonical=new ama.contract.MinutesContracts.CanonicalBudget(1000000,32,100000,65536,10000);return new TranscriptAcquisitionBudget(1000000,1000000,1000000,10000000,10000000,1000000,16,256,256).ledger(read,canonical,()->false);}
 static ama.contract.TaskContracts.TaskSpec spec(Map<String,Object> m){return JdbcPublicationService.spec(m,ledger());}
 static Map<String,Object> valid(){var m=new TreeMap<String,Object>();m.put("schema","ama.knowledge-publication-manifest.v1");for(String k:List.of("providerId","storeInstanceId","clientId","delegationKeyId","assertionKeyId","requesterId","libraryId","folderId"))m.put(k,"test-"+k);for(String k:List.of("publicationId","confirmationId","meetingId"))m.put(k,"00000000-0000-4000-8000-000000000001");m.put("renderArtifact",Map.of("version","test-v1","sha256","e".repeat(64)));m.put("businessKey",m.get("publicationId")+":"+m.get("confirmationId"));for(String k:List.of("logicalRequestHash","payloadSha256","archiveIndexSha256"))m.put(k,"a".repeat(64));m.put("businessVersion",1);m.put("cancelEpoch",0);m.put("executionNo",3);m.put("submissionNo",3);var prior=List.of(Map.of("executionId","00000000-0000-4000-8000-000000000002","executionRequestHash","b".repeat(64),"receiptId","receipt-"+"c".repeat(32),"proofDigest","d".repeat(64)));m.put("priorProofs",prior);m.put("bindingTransition",Map.of("schema","ama.controlled-kb-binding-transition.v1","expectedGeneration",1,"priorProofs",prior,"newBusinessKey",m.get("businessKey"),"newLogicalRequestHash",m.get("logicalRequestHash")));rehash(m);return m;}
 static void rehash(Map<String,Object> m){m.put("executionRequestHash",ControlledKnowledgeClient.digest(ControlledKnowledgeClient.canonical(Map.of("schema","ama.knowledge-publish-execution.v1","logicalRequestHash",m.get("logicalRequestHash"),"executionNo",m.get("executionNo"),"priorProofs",m.get("priorProofs")))));}
 @Test void validLocalOnlyGapAndFirstRequest(){assertDoesNotThrow(()->spec(valid()));var m=valid();m.put("priorProofs",List.of());m.put("executionNo",1);m.put("submissionNo",1);m.remove("bindingTransition");rehash(m);assertDoesNotThrow(()->spec(m));}
 @Test void missingOrNullTransitionCannotHideProofs(){for(int n=0;n<2;n++){var m=valid();if(n==0)m.remove("bindingTransition");else m.put("bindingTransition",null);assertThrows(RuntimeException.class,()->spec(m));}}
 @Test void transitionShapeAndIdentityAreExact(){for(String k:List.of("schema","newBusinessKey","newLogicalRequestHash","expectedGeneration","priorProofs","unexpected")){var m=valid();var t=new TreeMap<String,Object>((Map<String,Object>)m.get("bindingTransition"));t.put(k,k.equals("expectedGeneration")?2:k.equals("priorProofs")?List.of():"wrong");m.put("bindingTransition",t);assertThrows(RuntimeException.class,()->spec(m),k);}var m=valid();m.put("bindingTransition",List.of());assertThrows(RuntimeException.class,()->spec(m));}
 @Test void duplicateAndUnsortedPredecessorsRejected(){var m=valid();var one=((List<?>)m.get("priorProofs")).getFirst();m.put("priorProofs",List.of(one,one));rehash(m);assertThrows(RuntimeException.class,()->spec(m));}
 @Test void malformedShapeAndDigestRejected(){for(String k:List.of("executionRequestHash","businessKey","schema","extra")){var m=valid();m.put(k,"bad");assertThrows(RuntimeException.class,()->spec(m),k);}}
 @Test void originalWireMustBeCanonicalWithoutRewriting(){var m=valid();String original=new String(ControlledKnowledgeClient.canonical(m),java.nio.charset.StandardCharsets.UTF_8);assertDoesNotThrow(()->PublicationManifest.read(original,ledger()));for(String malformed:List.of(" "+original,original+"\n",original.replace("{","{ "))){assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read(malformed,ledger()),"Stored noncanonical wire must fail before worker or receipt admission");}}
 @Test void uniqueUnsortedPredecessorsAreRejected(){var m=valid();var one=new TreeMap<String,Object>((Map<String,Object>)((List<?>)m.get("priorProofs")).getFirst());var two=new TreeMap<String,Object>(one);two.put("executionId","00000000-0000-4000-8000-000000000003");m.put("priorProofs",List.of(two,one));var transition=new TreeMap<String,Object>((Map<String,Object>)m.get("bindingTransition"));transition.put("priorProofs",m.get("priorProofs"));transition.put("expectedGeneration",2);m.put("bindingTransition",transition);rehash(m);assertThrows(ama.contract.MinutesContracts.Failure.class,()->PublicationManifest.read(new String(ControlledKnowledgeClient.canonical(m),java.nio.charset.StandardCharsets.UTF_8),ledger()));}
}
